def encode_runs(text):
    if not text:
        return ""
    result = []
    prev = text[0]
    count = 1
    for ch in text[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{count}{prev}" if count > 1 else prev)
            prev = ch
            count = 1
    result.append(f"{count}{prev}" if count > 1 else prev)
    return "".join(result)
